def mod_pow(a, b, m):
	if b == 0:
		return 1
	if b == 1:
		return a % m
	tmp = mod_pow(a, b // 2, m)
	tmp = tmp * tmp % m
	if b % 2 == 1:
		tmp = tmp * a % m
	return tmp

def ncr(n, a, m, fact):
	first = mod_pow(fact[a], m - 2, m)
	second = mod_pow(fact[n - a], m - 2, m)
	res = fact[n] * first * second % m
	return res
